#!/usr/bin/env python3
"""
Modern Climate Data Analysis Script - Python 3
Replaces the legacy Python 2.7 climate analysis code.
"""

import configparser
from pathlib import Path

import numpy as np
import pandas as pd


class ClimateAnalyzer:
    def __init__(self, config_path: Path | None = None):
        self.config = configparser.ConfigParser()
        if config_path is not None and config_path.exists():
            self.config.read(config_path, encoding="utf-8")
        self.data_cache: dict = {}

    def load_temperature_data(self, filename: Path | str) -> pd.DataFrame:
        """Load temperature data using pandas with UTF-8 encoding."""
        path = Path(filename)
        df = pd.read_csv(path, encoding="utf-8")
        return df

    def calculate_station_mean(self, data: pd.DataFrame, station_id: int) -> float:
        """Calculate mean temperature for a specific station."""
        station_data = data[data["station_id"] == station_id]
        return float(station_data["temperature"].mean())

    def run_analysis(self, data_path: Path | str | None = None) -> None:
        """Main analysis pipeline."""
        if data_path is None:
            # Default to the sample data location relative to this script
            script_dir = Path(__file__).parent
            data_path = script_dir / "climate_analyzer" / "sample_data" / "climate_data.csv"

        data = self.load_temperature_data(data_path)

        # Process both stations (101 and 102)
        for station_id in [101, 102]:
            mean_temp = self.calculate_station_mean(data, station_id)
            print(f"Station {station_id} mean temperature: {mean_temp:.1f}°C")


if __name__ == "__main__":
    analyzer = ClimateAnalyzer()
    analyzer.run_analysis()

